[
  {
    "name": "男主（驾驶者）",
    "description": "30 岁出头的精英建筑师，全程未露正脸，以手部轮廓与侧影叙事",
    "appearance": "棱角分明的下颌线，修剪整齐的深栗色短发，骨节分明的手指",
    "costume": "深石墨色羊绒大衣，内搭黑色高领羊绒衫，无多余配饰",
    "personality": "克制、内省、向往自由"
  },
  {
    "name": "电动轿跑（主角）",
    "description": "全新豪华电动轿跑，银砂灰金属漆，流线型车身，全片第二主角",
    "appearance": "低趴宽体姿态，贯穿式灯带，21 英寸锻造轮毂，主动式尾翼",
    "costume": "无",
    "personality": "静如处子，动如脱兔"
  }
]

[
  {
    "name": "私人地下车库",
    "description": "男主住所的私人空间，作为仪式起点",
    "visualStyle": "顶部线性灯带勾勒车身剪影，地面抛光水泥反射，安静肃穆"
  },
  {
    "name": "黎明前空城",
    "description": "凌晨四点的城市 CBD，街道空无一人",
    "visualStyle": "深蓝天空残留最后一颗星，琥珀色路灯孤独亮着，玻璃幕墙反射冷月光"
  },
  {
    "name": "海滨高架公路",
    "description": "穿越城市后驶向大海的高架桥",
    "visualStyle": "天际线由深蓝渐变为钴蓝，远处海面泛着银灰微光"
  }
]

{
  "scenes": [
    {
      "location": "私人地下车库",
      "time": "凌晨 4:00 深夜",
      "characters": [
        "男主（驾驶者）",
        "电动轿跑（主角）"
      ],
      "action": "车库大门缓缓开启，灯带由暗渐亮。男主走入，绕车一周，指尖滑过引擎盖，在驾驶座停留片刻，发动引擎",
      "dialogue": "",
      "mood": "仪式感、肃穆、期待"
    },
    {
      "location": "黎明前空城",
      "time": "凌晨 4:15 黎明前",
      "characters": [
        "电动轿跑（主角）"
      ],
      "action": "车辆驶出车库，穿越无人的十字路口，掠过沉默的玻璃幕墙建筑群",
      "dialogue": "",
      "mood": "孤独、宁静、机械美学"
    },
    {
      "location": "海滨高架公路",
      "time": "凌晨 4:45 破晓",
      "characters": [
        "男主（驾驶者）",
        "电动轿跑（主角）"
      ],
      "action": "车汇入高架桥，天色由深蓝渐变为钴蓝。男主在断崖处停车，下车走向护栏，眺望海面第一缕光",
      "dialogue": "",
      "mood": "豁然、热血、释然"
    }
  ]
}
